function NetworkBurstFeatures = NetworkBurstFeatures(NetworkBurstDetected, spikeTimestamp, BurstDetected, range, netburst_member, units_participant, nBurst1, opt_secondary)

% function to analyze the network bursting activity by calculating XX different metrics on MEA-based recordings
% If there are secondary network burst events (echo or multicolumns), they will be analyzed separately

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%   INPUTS   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% structure array NetworkBurstDetection, generated by the funcion "NetworkBurstDetection", with the following field
%   .spikesBin(i,1):                total number of spikes in bin i
%   .time(i,1):                     midpoint of the bin i, in sec 
%   .nBurst:                        total number of network bursts
%   .IndivBurst(j).start            start point of network burst j, in sec
%   .IndivBurst(j).last             last point of network burst j, in sec
%   .IndivBurst(j).peak             peak point of network burst j, in sec
%   .IndivBurst(j).peakAmp          amplitude of the peak of network burst j
%   .IndivBurst(j).peakIdx:         peak point of network burst j
%   .IndivBurst(j).tail:            normalized tail of network burst j
%   .IndivBurst(j).window:          temporal window to extract spike train from network burst j, in ms
%   .Channels(i,1):                 list of channels that robustly participate of network bursting     
%   .parameter                      structure with information about the network burst detection method
%   .timeStamp{j,i}                 time stamp of the spikes for the burst j coming from channel i (all channels), in msec

%   netburst_member(i,1)            it indicates if the primary network burst event i is part of the analysis (=1) 
%   units_participant(i,1)          index of units participating of the primary network bursting under analysis
%   nBurst1                         total number of LEVEL-1 primary network burst events, i.e., the possible parents of the secondary events
%                                   (only used when opt_secondary = 1; revised October 2026: the callers passed the number of ALL primary events)
%   opt_secondary                   =0, it is a primary event;    =1, it is a secondary event

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%   OUTPUT   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% NetworkBurstFeatures.nBurstTotal                     % total number of network burst, across all families
% NetworkBurstFeatures.nBurst                          % total number of network burst, within the family under analysis
% NetworkBurstFeatures.nNeuron.totalRec                % total number of neurons (channels) in the recording
% NetworkBurstFeatures.nNeuron.totalBurst              % total number of neurons (channels) participating in network bursting, across all families
% NetworkBurstFeatures.nNeuron.normRec                 % total number of neurons (channels) participating in this family of network bursting, normalized to the total number of neurons in the recording
% NetworkBurstFeatures.nNeuron.normBurst               % total number of neurons (channels) participating in this family of network bursting, normalized to the total number of neurons in the recording


% NetworkBurstFeatures.nNeuron.norm                    % total number of neurons (channels) participating in network bursting, normalized to the total number of neurons
% NetworkBurstFeatures.rate.mean                       % mean rate of network bursting, in 1/min
% NetworkBurstFeatures.rate.cv                         % coefficient of variation for rate of network bursting (CV of the inter-burst intervals, peak to peak)
% NetworkBurstFeatures.rate.FF_cv2                     % (revised October 2026) Fano factor of the inter-burst intervals, as CV^2
% NetworkBurstFeatures.rate.FF_varmean                 % (revised October 2026) Fano factor of the inter-burst intervals, as variance / mean, in sec
% NetworkBurstFeatures.rate.FFcount                    % (revised October 2026) Fano factor of the number of network bursts in windows of COUNT_WINDOW sec
% NetworkBurstFeatures.rate.meanCount                  % (revised October 2026) mean number of network bursts per window
% NetworkBurstFeatures.rate.nWindows                   % (revised October 2026) number of windows
% NetworkBurstFeatures.amplitude.mean                  % mean amplitude (spike frequency) per neuron in network burst, in Hz 
% NetworkBurstFeatures.amplitude.cv                    % coefficient of variation of burst amplitude
% NetworkBurstFeatures.duration.mean                   % mean duration of network burst, in sec 
% NetworkBurstFeatures.duration.cv                     % coefficient of variation for duration of network burst 
% NetworkBurstFeatures.nSpikes.mean                    % total number of spikes per network burst, per channel 
% NetworkBurstFeatures.nSpikes.norm                    % total number of spikes in network burst, normalized to the total number of spikes in bursting participating neurons 
% NetworkBurstFeatures.nSpikes.normTotal               % total number of spikes in network burst, normalized to the total number of spikes across all channels
% NetworkBurstFeatures.distance.mean                   % distance of the network burst to the individual spike trains, in msec (peak to midpoint) 
% NetworkBurstFeatures.distance.cv
% NetworkBurstFeatures.delay.mean                      % distance of the burst start to the first spike of each spike train, in msec 
% NetworkBurstFeatures.neuronsAct.mean                 % mean number of active neurons within burst normalized to the total number of globally participating neurons
% NetworkBurstFeatures.neuronsAct.cv                   % coefficient of variation of # active neurons
% NetworkBurstFeatures.indivMetric(i).nSpikes          % total number of spikes in burst i, per channel
% NetworkBurstFeatures.indivMetric(i).duration         % duration of the burst i, in sec
% NetworkBurstFeatures.indivMetric(i).isi              % mean isi in burst i (across all channels), in msec
% NetworkBurstFeatures.indivMetric(i).nNeuronsAct      % normalized number of active neurons during burst i

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%   PARAMETERS   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

BIN_REF = 0.1;                              % reference bin size to calculate the height of a network burst, in sec (default: 0.1s = 100 msec)   

K_MSEC_SEC = 1/1000;                        % factor to rescale from msec to sec
K_SEC_MIN = 1/60;                           % factor to rescale from sec to min
COUNT_WINDOW = 60;                          % length of the windows to count the network bursts for the Fano factor of the counts, in sec (default: 60)
apply_parameters('NetworkBurstFeatures');                                   % (revised October 2026) values of the parameter set of "run_pipeline", if any (see "pipeline_parameters")

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Analyze the Network Bursting

nBurstTotal = NetworkBurstDetected.nBurst;
nBurst = numel(find(netburst_member));
nChTotal = size(spikeTimestamp,2);
nPartNeu = numel(units_participant);                                        % total number of neurons participating in this specific cluster of primary network bursts

% Basic features        
nNeuron = size(NetworkBurstDetected.Channels,1);                            % total number of neurons participating in primary network burst (revised October 2026:
                                                                            %  before the "if", so it is also defined for a family without events)
if ~isnan(nBurstTotal) && nBurstTotal>0 && nBurst>0                         % there is at least one network burst        

    % spikesBin = NetworkBurstDetected.spikesBin;
    % timeBin = NetworkBurstDetected.time;

    NetworkBurstFeatures.nBurstTotal = nBurstTotal;                         % total number of network burst, across all families
    NetworkBurstFeatures.nBurst = nBurst;                                   % total number of network burst, within the family under analysis
    NetworkBurstFeatures.nNeuron.totalRec = nChTotal;                       % total number of neurons (channels) in the recording
    NetworkBurstFeatures.nNeuron.totalBurst = nNeuron;                      % total number of neurons (channels) participating in network bursting, across all families
    NetworkBurstFeatures.nNeuron.Burst = nPartNeu;                          % total number of neurons (chnanels) participating in network bursting within the family
    NetworkBurstFeatures.nNeuron.normRec = nNeuron/nChTotal;                % total number of neurons (channels) participating in network bursting (across all families), normalized to the total number of neurons in the recording
    NetworkBurstFeatures.nNeuron.normBurst = nPartNeu/nNeuron;              % total number of neurons (channels) participating in this family of network bursting, normalized to the total number of neurons participating in network bursting (all families)

    delay = nan(nBurst,nPartNeu);
    isi_burst = nan(nBurst,1);
    peak_burst = nan(nBurst,1);
    duration_burst = nan(nBurst,1);
    spikes_burst = nan(nBurst,1);
    neurons_burst = nan(nBurst,1);
    distance_burst = nan(nBurst,1);
    height_burst = nan(nBurst,1);
    tail_burst = nan(nBurst,1);
    amplitudePop_burst = nan(nBurst,1); 
       
    idx_event = find(netburst_member);
    for k=1:nBurst                                                          % across all network burst events within the family
        idx = idx_event(k);
        IndivBurst = NetworkBurstDetected.IndivBurst(idx);                  % data correspondig to the network burst k    
        aux_spikes = nan(nPartNeu,1);                                       % for the number of spikes 
        distance = nan(nPartNeu,1);                                         % for the peak-to-peak distance
        isi = nan(nPartNeu,1);                                              % for the mean isi
                    
        peak_burst(k) = IndivBurst.peak;                                    % location of the peak of the network burst
        aux_timeStamp_full = cell(nPartNeu,1);
        aux_timeStamp = cell(nPartNeu,1);
                    
        % Re-shape the spike train !!!!

        n_active = 0;                                                       % number of active neurons
        for ch=1:nPartNeu                                                   % across all robustly participating neurons in this family of network bursts
            %idx_ch = NetworkBurstDetected.Channels(ch,1);       % index of the channel/neuron ch
            idx_ch = units_participant(ch);                                 % index of the channel/neuron ch
            aux_timeStamp_full{ch} = NetworkBurstDetected.timeStamp{idx,idx_ch};   % time stamp of the spikes from neuron ch during burst k
            aux_timeStamp{ch} = aux_timeStamp_full{ch}(intersect(find(aux_timeStamp_full{ch}>IndivBurst.start/K_MSEC_SEC),find(aux_timeStamp_full{ch}<IndivBurst.last/K_MSEC_SEC)));
            aux_spikes(ch) = numel(aux_timeStamp{ch});                      % number of spikes from neuron ch during burst k    
                        
            if aux_spikes(ch)>1                                 
                isi(ch) = median(diff(aux_timeStamp{ch}), 'omitnan');                  % median isi for the neuron ch during event k    
            end
            if aux_spikes(ch)>0
                midpoint = median(aux_timeStamp{ch});
                distance(ch) = peak_burst(k)/K_MSEC_SEC - midpoint;          % distance of the spike train of cluster ch to the peak of the burst, in msec
                delay(k, ch) = IndivBurst.start/K_MSEC_SEC - aux_timeStamp{ch}(1);     % delay of the cluster ch for the burst k
                n_active = n_active + 1;                                    % total number of active neurons during the burst k
            end
        end
                    
        NetworkBurstFeatures.indivMetric(k).nSpikes = mean(aux_spikes,'omitnan');                           % total number of spikes in burst idx, per channel
        NetworkBurstFeatures.indivMetric(k).duration = IndivBurst.last - IndivBurst.start;                  % duration of the burst k, in sec
        NetworkBurstFeatures.indivMetric(k).distance = mean(abs(distance),'omitnan');                       % distance of the network burst idx to the individual spike trains, in msec (peak to midpoint);
        NetworkBurstFeatures.indivMetric(k).isi = mean(isi, 'omitnan');                                     % mean isi in burst k (across all channels), in msec
        NetworkBurstFeatures.indivMetric(k).nNeuronsAct = n_active/nPartNeu;                                % number of active neurons during burst k, normalized to the total number of participating units in this family of network bursts
        NetworkBurstFeatures.indivMetric(k).tail = IndivBurst.tail;
        NetworkBurstFeatures.indivMetric(k).amplitudePop = IndivBurst.peakAmp;                              % amplitude of the burst k, from the population firing rate
        NetworkBurstFeatures.indivMetric(k).level = IndivBurst.level;                              
        
        isi_burst(k) = NetworkBurstFeatures.indivMetric(k).isi;             % mean isi in burst k (across all channels), in msec
        duration_burst(k) = NetworkBurstFeatures.indivMetric(k).duration;   % duration of the burst k, in sec
        spikes_burst(k) = NetworkBurstFeatures.indivMetric(k).nSpikes;      % total number of spikes in event k              
        neurons_burst(k) = NetworkBurstFeatures.indivMetric(k).nNeuronsAct; % normalized number of active neurons during burst k
        distance_burst(k) = NetworkBurstFeatures.indivMetric(k).distance;   % distance of the network burst k to the individual spike trains, in msec (peak to midpoint)    
        tail_burst(k) = NetworkBurstFeatures.indivMetric(k).tail;
        amplitudePop_burst(k) = NetworkBurstFeatures.indivMetric(k).amplitudePop;
        
        charge = sum(aux_spikes);                                           % total number of spikes across all participating neurons
        %factor = (spikesBin(1,3) - spikesBin(1,2))/BIN_REF;                % normalization factor
        %factor = (timeBin(2) - timeBin(1))/BIN_REF;                         % normalization factor
        %peak_height = spikesBin(IndivBurst.peakIdx,1);                      % peak number of spikes during burst k
        factor = NetworkBurstDetected.bin / BIN_REF;                        % normalization factor
        peak_height = IndivBurst.peakAmp;                                   % amplitude of the peak
        if charge > 0                                                       % (revised October 2026) NaN (ignored by the mean) instead of Inf, if there are no spikes
            height_burst(k) = (peak_height/factor/charge)/duration_burst(k);    % normalized height of the burst k
        end

        clear aux_spikes IndivBurst aux_timeStamp isi n_active distance aux_timeStamp_full
    end   % end of the for loop acroos all burst events
            
    % Counting spikes
    spikes_neuron_netBursting = 0;
    for ch=1:nPartNeu
%        idx_ch = NetworkBurstDetected.Channels(ch,1);               % index of the channel/neuron ch
        idx_ch = units_participant(ch);                                                         % index of the channel/neuron ch
        spikes_neuron_netBursting = spikes_neuron_netBursting + spikeTimestamp(idx_ch).nUnits;  % total number of spikes from participating neurons
    end
            
    spikes_neuron_total = 0;
    for i=1:nChTotal
        spikes_neuron_total = spikes_neuron_total + spikeTimestamp(i).nUnits;                   % total number of spikes across all neurons in the recording
    end
            
    % Inter-burst interval
    if nBurst>1
        ibi = diff(peak_burst);
        NetworkBurstFeatures.rate.mean = 1/(mean(ibi,'omitnan')*K_SEC_MIN);
        NetworkBurstFeatures.rate.cv = std(ibi,'omitnan')/mean(ibi,'omitnan');
        NetworkBurstFeatures.rate.FF_cv2 = NetworkBurstFeatures.rate.cv^2;                  % (revised October 2026) Fano factor of the inter-burst intervals, as CV^2
        NetworkBurstFeatures.rate.FF_varmean = var(ibi,'omitnan')/mean(ibi,'omitnan');      % (revised October 2026) as variance / mean, in sec
    else
        NetworkBurstFeatures.rate.mean = nan;
        NetworkBurstFeatures.rate.cv = nan;
        NetworkBurstFeatures.rate.FF_cv2 = nan;
        NetworkBurstFeatures.rate.FF_varmean = nan;
    end
    % (revised October 2026) network bursts of this family counted in windows of COUNT_WINDOW sec, along the analysis window (by the time of their peak)
    counting = countFanoFactor(peak_burst/K_MSEC_SEC, range*K_MSEC_SEC, COUNT_WINDOW);   % (peaks in sec -> msec; "range" in msec -> sec)
    NetworkBurstFeatures.rate.FFcount = counting.FFcount;                                % Fano factor of the counts
    NetworkBurstFeatures.rate.meanCount = counting.meanCount;                            % mean number of network bursts per window
    NetworkBurstFeatures.rate.nWindows = counting.nWindows;                              % number of windows
             
    % Prepare the results
    NetworkBurstFeatures.amplitude.mean = 1/(mean(isi_burst,'omitnan')*K_MSEC_SEC);
    NetworkBurstFeatures.amplitude.cv = std(isi_burst,'omitnan')/mean(isi_burst,'omitnan');
    NetworkBurstFeatures.duration.mean = mean(duration_burst,'omitnan');
    NetworkBurstFeatures.duration.cv = std(duration_burst,'omitnan')/mean(duration_burst,'omitnan');
    NetworkBurstFeatures.nSpikes.mean = mean(spikes_burst,'omitnan');           % total number of spikes per network burst, per neuron 
    NetworkBurstFeatures.nSpikes.norm = mean(spikes_burst,'omitnan')*nBurst/(spikes_neuron_netBursting/nPartNeu);  % total number of spikes in network burst, normalized to the total number of spikes in bursting participating neurons 
    NetworkBurstFeatures.nSpikes.normTotal = mean(spikes_burst,'omitnan')*nBurst*nPartNeu/spikes_neuron_total;     % total number of spikes in network burst, normalized to the total number of spikes across all channels
    NetworkBurstFeatures.neuronsAct.mean = mean(neurons_burst,'omitnan');       % number of active neurons within burst normalized to the total number of globally participating neurons
    NetworkBurstFeatures.neuronsAct.cv = std(neurons_burst,'omitnan')/mean(neurons_burst,'omitnan');      
    NetworkBurstFeatures.distance.mean = mean(distance_burst,'omitnan');        % distance of the network burst to the individual spike trains, in msec (peak to midpoint)
    NetworkBurstFeatures.distance.cv = std(distance_burst,'omitnan')/mean(distance_burst,'omitnan');      
    aux = mean(abs(delay),2,'omitnan');            
    NetworkBurstFeatures.delay.mean = mean(aux,'omitnan');                      % distance of the burst start to the first spike of each spike train, in msec
    NetworkBurstFeatures.delay.cv = std(aux,'omitnan')/mean(aux,'omitnan');      
    NetworkBurstFeatures.delay.values = delay;
    NetworkBurstFeatures.height.mean = mean(height_burst, 'omitnan');                % normalized height 
    NetworkBurstFeatures.height.cv = std(height_burst,'omitnan')/mean(height_burst,'omitnan');                % normalized height 
    NetworkBurstFeatures.tail.mean = mean(tail_burst, 'omitnan');                % normalized tail 
    NetworkBurstFeatures.tail.cv = std(tail_burst,'omitnan')/mean(tail_burst,'omitnan');                % normalized tail 
    NetworkBurstFeatures.amplitudePop.mean = mean(amplitudePop_burst, 'omitnan');                 
    NetworkBurstFeatures.amplitudePop.cv = std(amplitudePop_burst,'omitnan')/mean(amplitudePop_burst,'omitnan');                 
else
    
    NetworkBurstFeatures.nBurstTotal = nBurstTotal;                         % total number of network burst, across all families
    NetworkBurstFeatures.nBurst = 0;            
    NetworkBurstFeatures.nNeuron.totalRec = nChTotal;                       % total number of neurons (channels) in the recording
    if nBurstTotal==0 || isnan(nBurstTotal)
        nNeuron = 0;
    end
    NetworkBurstFeatures.nNeuron.totalBurst = nNeuron;                  % total number of neurons (channels) participating in network bursting, across all families
    NetworkBurstFeatures.nNeuron.Burst = [];                                % total number of neurons (chnanels) participating in network bursting within the family
    NetworkBurstFeatures.nNeuron.normRec = nNeuron/nChTotal;                % total number of neurons (channels) participating in network bursting (across all families), normalized to the total number of neurons in the recording
    NetworkBurstFeatures.nNeuron.normBurst = [];                            % total number of neurons (channels) participating in this family of network bursting, normalized to the total number of neurons participating in network bursting (all families)
    NetworkBurstFeatures.rate.mean = [];
    NetworkBurstFeatures.rate.cv = [];
    NetworkBurstFeatures.rate.FF_cv2 = [];
    NetworkBurstFeatures.rate.FF_varmean = [];
    NetworkBurstFeatures.rate.FFcount = [];
    NetworkBurstFeatures.rate.meanCount = [];
    NetworkBurstFeatures.rate.nWindows = [];
    NetworkBurstFeatures.amplitude.mean = [];
    NetworkBurstFeatures.amplitude.cv = [];
    NetworkBurstFeatures.duration.mean = [];
    NetworkBurstFeatures.duration.cv = [];
    NetworkBurstFeatures.nSpikes.mean = [];
    NetworkBurstFeatures.nSpikes.norm = [];
    NetworkBurstFeatures.nSpikes.normTotal = [];
    NetworkBurstFeatures.neuronsAct.mean = [];
    NetworkBurstFeatures.neuronsAct.cv = [];
    NetworkBurstFeatures.distance.mean = [];
    NetworkBurstFeatures.distance.cv = [];
    NetworkBurstFeatures.delay.mean = [];
    NetworkBurstFeatures.delay.cv = [];
    NetworkBurstFeatures.delay.values = [];
    NetworkBurstFeatures.height.mean = []; 
    NetworkBurstFeatures.height.cv = []; 
    NetworkBurstFeatures.tail.mean = []; 
    NetworkBurstFeatures.tail.cv = [];  
    NetworkBurstFeatures.amplitudePop.mean = [];                 
    NetworkBurstFeatures.amplitudePop.cv = [];                 
end

if opt_secondary
    if ~isnan(nBurstTotal) && nBurstTotal>0 && nBurst>0                     % there is at least one secondary network burst 
        daughter = zeros(nBurst1,1);                                        % total number of secondary peaks per primary event
        for k=1:nBurst                                                      % across all network burst events within the family
            idx = idx_event(k);
            IndivBurst = NetworkBurstDetected.IndivBurst(idx);              % data correspondig to the network burst k    
            daughter(IndivBurst.parent) = daughter(IndivBurst.parent) + 1;  % total of secondary events associated to each primary network event
        end
        NetworkBurstFeatures.PrimarywithSecondary = numel(find(daughter>0))/nBurst1;   % proportion of (level-1) primary network burst events with an associated secondary event
        NetworkBurstFeatures.SecondaryperPrimary = mean(daughter, 'omitnan');          % number of secondary network burst events per primary event
    else
        NetworkBurstFeatures.PrimarywithSecondary = [];
        NetworkBurstFeatures.SecondaryperPrimary = [];
    end
end

end